"""Authored reading material. Run only when editing the bank; no runtime AI."""
import json
from pathlib import Path
bank=[]
def add(level,slug,title,topic,story,questions):
    paragraphs=[p.strip().replace('\n',' ') for p in story.strip().split('\n\n')]
    qs=[]
    for line in questions.strip().split('\n'):
        question,correct,a,b,c,evidence,explanation=line.split('|')
        assert evidence in ' '.join(paragraphs),(slug,evidence)
        opts=[correct,a,b,c]
        shift=(len(bank)+len(qs))%4
        opts=opts[shift:]+opts[:shift]
        assert len(set(opts))==4
        qs.append(dict(question=question,options=opts,answer=(-shift)%4,evidence=evidence,explanation=explanation))
    bank.append(dict(id='reading-v39-'+slug,level=level,title=title,topic=topic,paragraphs=paragraphs,questions=qs,source='starter'))

